        topics: ["Teologi","Eskatologi","Soteriologi","Eklesiologi","Moral","Etika","Sakramen","Liturgi","Misi","Pelayanan"],
        facts: ["Teologi adalah ilmu tentang Allah, Yesus Kristus, Roh Kudus, dan Alkitab.","Eskatologi adalah ilmu tentang akhirat, kematian, penghakiman, dan kehidupan kekal.","Soteriologi adalah ilmu tentang keselamatan melalui iman kepada Yesus Kristus.","Eklesiologi adalah ilmu tentang gereja, struktur, fungsi, dan misi gereja.","Moral adalah nilai-nilai baik dan buruk yang diajarkan dalam agama Katolik.","Etika adalah ilmu tentang moral dan perilaku yang benar.","Sakramen adalah upacara suci dalam agama Katolik seperti baptis dan perjamuan kudus.","Liturgi adalah tata cara ibadah dalam agama Katolik.","Misi adalah tugas gereja untuk menyebarkan Injil dan melayani sesama.","Pelayanan adalah tugas gereja untuk melayani jemaat dan masyarakat."],
        quiz: [{"q":"Apa yang dimaksud dengan teologi?","options":["Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan","Ilmu tentang gereja"],"a":0,"type":"mcq"},{"q":"Apa yang dimaksud dengan eskatologi?","options":["Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan","Ilmu tentang gereja"],"a":1,"type":"mcq"},{"q":"Apa yang dimaksud dengan soteriologi?","options":["Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan","Ilmu tentang gereja"],"a":2,"type":"mcq"},{"q":"Apa yang dimaksud dengan eklesiologi?","options":["Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan","Ilmu tentang gereja"],"a":3,"type":"mcq"},{"q":"Apa yang dimaksud dengan moral?","options":["Nilai baik dan buruk","Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan"],"a":0,"type":"mcq"},{"q":"Apa yang dimaksud dengan etika?","options":["Ilmu tentang moral","Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan"],"a":0,"type":"mcq"},{"q":"Apa yang dimaksud dengan sakramen?","options":["Upacara suci","Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan"],"a":0,"type":"mcq"},{"q":"Apa yang dimaksud dengan liturgi?","options":["Tata cara ibadah","Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan"],"a":0,"type":"mcq"},{"q":"Apa yang dimaksud dengan misi?","options":["Tugas gereja","Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan"],"a":0,"type":"mcq"},{"q":"Apa yang dimaksud dengan pelayanan?","options":["Tugas melayani","Ilmu tentang Allah","Ilmu tentang akhirat","Ilmu tentang keselamatan"],"a":0,"type":"mcq"},{"q":"Teologi meliputi?","options":["Teologi sistematis, teologi historis, teologi praktis","Hanya teologi sistematis","Hanya teologi historis","Hanya teologi praktis"],"a":0,"type":"mcq"},{"q":"Eskatologi meliputi?","options":["Eskatologi individual, eskatologi universal, eskatologi akhir","Hanya eskatologi individual","Hanya eskatologi universal","Hanya eskatologi akhir"],"a":0,"type":"mcq"},{"q":"Soteriologi meliputi?","options":["Soteriologi historis, soteriologi sistematis, soteriologi praktis","Hanya soteriologi historis","Hanya soteriologi sistematis","Hanya soteriologi praktis"],"a":0,"type":"mcq"},{"q":"Eklesiologi meliputi?","options":["Eklesiologi historis, eklesiologi sistematis, eklesiologi praktis","Hanya eklesiologi historis","Hanya eklesiologi sistematis","Hanya eklesiologi praktis"],"a":0,"type":"mcq"},{"q":"Moral meliputi?","options":["Moral individual, moral sosial, moral politik","Hanya moral individual","Hanya moral sosial","Hanya moral politik"],"a":0,"type":"mcq"},{"q":"Etika meliputi?","options":["Etika Katolik, etika sosial, etika lingkunen","Hanya etika Katolik","Hanya etika sosial","Hanya etika lingkunen"],"a":0,"type":"mcq"},{"q":"Sakramen meliputi?","options":["Baptis, perjamuan kudus, peneguhan","Hanya baptis","Hanya perjamuan kudus","Hanya peneguhan"],"a":0,"type":"mcq"},{"q":"Liturgi meliputi?","options":["Ibadah, doa, nyanyian, kotbah","Hanya ibadah","Hanya doa","Hanya nyanyian"],"a":0,"type":"mcq"},{"q":"Misi meliputi?","options":["Misi lokal, misi nasional, misi internasional","Hanya misi lokal","Hanya misi nasional","Hanya misi internasional"],"a":0,"type":"mcq"},{"q":"Pelayanan meliputi?","options":["Pelayanan sosial, pelayanan pendidikan, pelayanan kesehatan","Hanya pelayanan sosial","Hanya pelayanan pendidikan","Hanya pelayanan kesehatan"],"a":0,"type":"mcq"}]
